:root {
    --bg: #0a0f14;
    --text: #e8e6e3;
    --accent: #7eb8da;
    --muted: #8b9298;
    --border: #2a3540;
}

* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

body {
    font-family: 'Georgia', serif;
    background: var(--bg);
    color: var(--text);
    line-height: 1.7;
    font-size: 18px;
}

main {
    max-width: 720px;
    margin: 0 auto;
    padding: 4rem 2rem;
}

header {
    margin-bottom: 3rem;
    text-align: center;
}

h1 {
    font-size: 2.5rem;
    font-weight: 400;
    letter-spacing: 0.02em;
    margin-bottom: 0.5rem;
    color: var(--accent);
}

.tagline {
    color: var(--muted);
    font-style: italic;
    font-size: 1.1rem;
}

section {
    margin-bottom: 3rem;
}

h2 {
    font-size: 1.4rem;
    font-weight: 400;
    color: var(--accent);
    margin-bottom: 1rem;
    padding-bottom: 0.5rem;
    border-bottom: 1px solid var(--border);
}

h3 {
    font-size: 1.1rem;
    font-weight: 600;
    margin-bottom: 0.5rem;
}

p {
    margin-bottom: 1rem;
}

ul {
    margin: 1rem 0 1rem 1.5rem;
}

li {
    margin-bottom: 0.75rem;
}

a {
    color: var(--accent);
    text-decoration: none;
}

a:hover {
    text-decoration: underline;
}

.focus-areas {
    display: grid;
    gap: 1.5rem;
    margin-top: 1.5rem;
}

.area {
    padding: 1.5rem;
    border: 1px solid var(--border);
    border-radius: 4px;
}

.area h3 {
    color: var(--text);
}

.area p {
    color: var(--muted);
    margin-bottom: 0;
    font-size: 0.95rem;
}

.contact {
    background: linear-gradient(135deg, rgba(126, 184, 218, 0.1) 0%, transparent 100%);
    padding: 2rem;
    border-radius: 4px;
    border: 1px solid var(--border);
}

footer {
    margin-top: 4rem;
    text-align: center;
    color: var(--muted);
    font-size: 0.9rem;
}

@media (max-width: 600px) {
    body { font-size: 16px; }
    h1 { font-size: 2rem; }
    main { padding: 2rem 1rem; }
}

